from pathlib import Path
ROOT=Path(__file__).parent
NAV=[('home','首页','index.html'),('features','功能','features.html'),('guide','使用指南','guide.html'),('download','下载','download.html')]
def header(page):
    links=''.join(f'<a href="{url}"'+(' aria-current="page"' if key==page else '')+f'>{name}</a>' for key,name,url in NAV)
    return '<a class="skip" href="#main">跳到主要内容</a><header class="site-header"><div class="shell nav-shell"><a class="brand" href="index.html" aria-label="Crossbow 首页"><img src="assets/logo.png" alt="" width="36" height="36"><span>Crossbow</span></a><button class="menu-button" aria-expanded="false" aria-controls="site-nav">菜单 <span aria-hidden="true">＋</span></button><nav id="site-nav" aria-label="主导航">'+links+'<a class="github-link" href="https://github.com/Richard-Zhang1019/Crossbow" target="_blank" rel="noopener">GitHub <span aria-hidden="true">↗</span></a></nav></div></header>'
def footer():
    return '<footer class="site-footer"><div class="shell footer-shell"><span>© 2026 Crossbow</span><div><a href="https://github.com/Richard-Zhang1019/Crossbow/blob/main/LICENSE" target="_blank" rel="noopener">GPL 3.0 开源</a><a href="privacy.html">隐私说明</a><a href="https://github.com/Richard-Zhang1019/Crossbow/issues" target="_blank" rel="noopener">反馈问题 ↗</a></div></div></footer>'
def page(key,title,body,home=False):
    return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#ffffff"><meta name="description" content="Crossbow 开源桌面代理客户端。管理订阅与节点，控制系统代理和 TUN，查看连接、日志和网络诊断。"><meta property="og:title" content="'+title+' · Crossbow"><title>'+title+' · Crossbow</title><link rel="icon" href="assets/favicon.png"><link rel="stylesheet" href="style.css"><script src="site.js" defer></script></head><body class="'+('home-page' if home else 'inner-page')+'">'+header(key)+body+footer()+'</body></html>'
monitor='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/></svg>'
sliders='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18M7 3v6m10 0v6M9 15v6"/></svg>'
globe='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18M12 3c-5 5-5 13 0 18M5 6.5c4 3 10 3 14 0M5 17.5c4-3 10-3 14 0"/></svg>'
home='''<main id="main" class="home-main shell"><div class="home-intro"><h1>让连接，清晰可见。</h1><p>macOS 与 Windows 的开源代理客户端。<br class="mobile-break">管理订阅与节点，也看清每一步连接。</p></div><div class="flow-stage" role="img" aria-label="你的设备，经规则分流，连接目标网络"><div class="flow-node device">'''+monitor+'''<b>你的设备</b><span class="desktop-copy">macOS / Windows</span><span class="mobile-copy">桌面设备</span></div><div class="flow-track first" aria-hidden="true"></div><div class="flow-node routing">'''+sliders+'''<b>规则分流</b><span>按需连接</span></div><div class="flow-track second" aria-hidden="true"></div><div class="flow-node destination">'''+globe+'''<b>目标网络</b><span>代理 / 直连</span></div><div class="flow-lane" aria-hidden="true"><i class="packet"></i></div></div><div class="home-action"><a class="primary-button" href="download.html">下载 Crossbow <span aria-hidden="true">↓</span></a><p>开源客户端，自备节点或配置。</p></div><button class="pause-button" aria-pressed="false" aria-label="暂停连接路径动效"><svg viewBox="0 0 20 20" aria-hidden="true"><path class="pause-shape" d="M7 5v10M13 5v10"/><path class="play-shape" d="m7 5 7 5-7 5z"/></svg><span>暂停动效</span></button></main>'''
features='''<main id="main" class="shell page-main"><header class="page-intro"><h1>从连接，到掌控。</h1><p>让选择有依据，让问题有线索。<br>把订阅、节点、接管和监测，放进同一套工作流。</p></header><nav class="section-nav" aria-label="功能目录"><a href="#nodes">节点与分流</a><a href="#takeover">接管方式</a><a href="#profiles">配置与内核</a><a href="#observe">监测与诊断</a></nav><section class="feature-row" id="nodes"><div><h2>选节点，不靠猜。</h2><p>先找到合适的节点，再决定怎么连接。</p></div><div class="feature-details"><article><h3>搜索、筛选与排序</h3><p>搜索节点名称或协议，按地区收拢节点；筛选可用结果，按延迟排序。</p></article><article><h3>测速状态原位展示</h3><p>支持单节点与整组测试。测速中的状态、返回的延迟和超时结果都留在原位。</p></article><article><h3>自动选择，也能手动切换</h3><p>根据配置使用自动选择，或手动指定节点；直连、规则与全局模式按场景切换。</p></article></div></section><section class="feature-row" id="takeover"><div><h2>怎么接管，由你决定。</h2><p>系统代理和 TUN 各有用途，也可以同时开启。</p></div><div class="feature-details"><article><h3>系统代理</h3><p>让遵循系统代理设置的应用，经由 Crossbow 连接。适合浏览器等常用应用。</p></article><article><h3>TUN 模式</h3><p>用虚拟网卡接管系统流量，覆盖不读取系统代理的应用。首次使用需完成对应平台的授权或服务配置。</p></article><article><h3>菜单栏与托盘</h3><p>实时查看上下行速率，快速切换节点与接管方式，不必每次返回主窗口。</p></article></div></section><section class="feature-row" id="profiles"><div><h2>配置，按自己的习惯。</h2><p>原始配置与个性化修改，分别管理。</p><div class="engine-type"><span>mihomo</span><span>sing-box</span></div></div><div class="feature-details"><article><h3>订阅与本地文件</h3><p>导入已有订阅链接或本地配置，管理多个配置来源，并设置订阅更新周期。</p></article><article><h3>Merge 与 Script 覆写</h3><p>合并配置片段，或通过脚本整理配置。将自己的修改绑定到需要的配置来源。</p></article><article><h3>双内核选择</h3><p>按配置需要选择 mihomo 或 sing-box。协议和规则兼容性以所选内核为准，切换后仍需验证配置。</p></article></div></section><section class="feature-row" id="observe"><div><h2>连接有迹，问题可查。</h2><p>从连接去向，到日志和诊断，逐层寻找线索。</p></div><div class="feature-details"><article><h3>连接与流量</h3><p>查看目标站点、命中规则、出口与流量，了解连接实际走向。</p></article><article><h3>内核日志与网络诊断</h3><p>查看运行日志，检查内核、控制器、端口、代理和 DNS 等环节。反馈问题时可复制脱敏详情。</p></article><article><h3>站点连通性测试</h3><p>检测 YouTube、X、Google、GitHub 的站点响应。测试结果是排查线索，实际使用仍需由常用应用验证。</p></article></div></section><div class="page-next"><p>准备好一份配置，就可以开始。</p><a href="guide.html">查看使用指南 <span aria-hidden="true">→</span></a></div></main>'''
guide='''<main id="main" class="shell page-main"><header class="page-intro"><h1>从一份配置开始。</h1><p>安装、导入、选择连接方式。<br>Crossbow 是客户端，需要你自己准备节点或订阅。</p></header><div class="guide-layout"><aside class="guide-index"><nav aria-label="指南目录"><a href="#install">安装客户端</a><a href="#import">导入配置</a><a href="#connect">开始连接</a><a href="#diagnose">遇到问题</a><a href="#faq">常见问题</a></nav></aside><div class="guide-content"><section id="install"><h2>安装客户端</h2><p>在官方 GitHub Releases 中选择与你设备匹配的安装包。当前公开提供 macOS Apple Silicon 和 Windows x64 版本。</p><p>下载后按安装说明操作，校验文件可参考同一版本附带的 SHA256SUMS。</p><a class="inline-link" href="download.html">选择下载版本 →</a></section><section id="import"><h2>导入你的配置</h2><p>打开「配置」，添加订阅链接或导入本地文件，再选中要使用的配置来源。订阅可以按周期更新；需要个性化修改时，再配置 Merge 或 Script 覆写。</p><p>Crossbow 不提供节点或订阅服务。配置中可能包含凭据，请妥善保存。</p></section><section id="connect"><h2>选择节点，开始连接</h2><p>在节点页进行延迟测试，选择节点或自动选择策略，再开启适合自己的接管方式。</p><dl class="guide-options"><div><dt>系统代理</dt><dd>适用于遵循系统代理设置的应用。</dd></div><div><dt>TUN 模式</dt><dd>通过虚拟网卡接管流量，首次使用需完成相应授权或服务配置。</dd></div></dl><p>两种方式可以独立控制或同时开启。请选择自己的常用应用验证实际访问情况。</p></section><section id="diagnose"><h2>有问题，先看链路。</h2><p>先确认配置和节点有效，再查看连接、日志和诊断。可以结合站点连通性测试，区分节点响应、目标站点与应用代理设置的问题。</p><p>如果同时运行其他代理或 VPN，请避免重复接管或路由冲突。反馈问题时附上版本、操作系统和脱敏后的诊断内容。</p><a class="inline-link" href="https://github.com/Richard-Zhang1019/Crossbow/issues" target="_blank" rel="noopener">在 GitHub 反馈问题 ↗</a></section><section id="faq"><h2>常见问题</h2><div class="faq"><details name="faq"><summary>测速成功，就一定可以访问吗？<span aria-hidden="true">＋</span></summary><p>不一定。延迟测试、站点响应与浏览器实际访问是不同检查。结合连接列表、日志和实际应用表现判断。</p></details><details name="faq"><summary>系统代理与 TUN 能同时打开吗？<span aria-hidden="true">＋</span></summary><p>可以，两个开关独立控制，共用本应用内核。使用其他代理或 VPN 时应避免路由冲突。</p></details><details name="faq"><summary>两种内核的配置通用吗？<span aria-hidden="true">＋</span></summary><p>不一定。协议、规则和配置兼容性以所选 mihomo 或 sing-box 内核为准。</p></details><details name="faq"><summary>iOS 可以下载了吗？<span aria-hidden="true">＋</span></summary><p>iOS 仍在开发验证，目前没有公开分发入口。公开下载平台以官方 Release 资产为准。</p></details><details name="faq"><summary>如何检查更新？<span aria-hidden="true">＋</span></summary><p>在应用的设置页检查更新，或前往官方 GitHub Releases 查看版本说明与安装包。</p></details><details name="faq"><summary>提交问题时，哪些信息不能公开？<span aria-hidden="true">＋</span></summary><p>不要公开订阅链接、token、节点密码等凭据。只提供版本、系统、复现步骤和脱敏后的日志或诊断内容。</p></details></div></section></div></div></main>'''
download='''<main id="main" class="shell page-main download-main"><header class="page-intro"><h1>选择你的桌面版。</h1><p>从官方 GitHub Releases 获取安装包。<br>版本说明与校验文件，也在同一处。</p></header><div class="download-list"><a href="https://github.com/Richard-Zhang1019/Crossbow/releases/latest" target="_blank" rel="noopener" class="platform-link"><div><h2>macOS</h2><p>Apple Silicon · DMG</p></div><span>前往下载 <b aria-hidden="true">↗</b></span></a><a href="https://github.com/Richard-Zhang1019/Crossbow/releases/latest" target="_blank" rel="noopener" class="platform-link"><div><h2>Windows</h2><p>x64 · 安装程序</p></div><span>前往下载 <b aria-hidden="true">↗</b></span></a><div class="platform-link development"><div><h2>iOS</h2><p>开发验证中，暂未公开分发。</p></div><span>开发中</span></div></div><div class="download-help"><h2>第一次使用？</h2><p>你需要准备已有的订阅或本地配置。Crossbow 是开源客户端，不包含节点服务。</p><a class="inline-link" href="guide.html">查看使用指南 →</a></div></main>'''
privacy='''<main id="main" class="shell page-main policy"><header class="page-intro"><h1>隐私说明</h1><p>本地官网设计原型的说明。</p></header><section><h2>关于这个预览</h2><p>设计稿不提交配置、不连接代理内核，不使用追踪脚本。字体、标志与页面源码均随版本保存。路径动效只用于解释产品功能，不反映本机网络状态。</p><h2>外部链接</h2><p>点击下载、源码或问题反馈入口后，会进入 GitHub。正式网站的托管与产品隐私政策需在上线前单独确认，本页不代替完整产品政策。</p><h2>保护你的配置</h2><p>订阅和配置可能包含凭据，反馈问题前请脱敏，不公开 token、服务器密码或私有订阅地址。</p></section></main>'''
for filename,key,title,content in [('index.html','home','让连接，清晰可见',home),('features.html','features','功能',features),('guide.html','guide','使用指南',guide),('download.html','download','下载',download),('privacy.html','','隐私说明',privacy)]:
    (ROOT/filename).write_text(page(key,title,content,filename=='index.html'))
notfound='<main id="main" class="shell page-main policy"><header class="page-intro"><h1>这条路径还未连接。</h1><p>没有找到这个页面。</p></header><a href="index.html" class="primary-button">返回首页 →</a></main>'
(ROOT/'404.html').write_text(page('','页面未找到',notfound))
